-- Monthly salary package (basic + fixed allowances of the latest open salary record) by branch and Saudi / non-Saudi. Columns: br, sa, n, sal, mx, mn
-- Tie: sum(sal) is the monthly salary roll (2,332,560 at Al Faihaa). PR_STAFF_DEFAULT_SALARY_M holds basic, _D the fixed items.
SELECT (CASE WHEN x.ORG IN ('001','002','003','004') THEN '0'||SUBSTR(x.ORG,3,1) ELSE SUBSTR(x.ORG,1,2) END) BR, CASE WHEN x.NAT={SAUDI} THEN 'S' ELSE 'N' END SA, COUNT(*) N, ROUND(SUM(x.TOT)) SAL, ROUND(MAX(x.TOT)) MX, ROUND(MIN(x.TOT)) MN FROM (SELECT m.nationality_code NAT, (SELECT MAX(t.ORGANIZATION_NO) FROM {P}PS_STAFF_INTERNAL_TRANSFERS t WHERE t.STAFF_ID=c.STAFF_ID AND t.CURRENT_JOB='Y') ORG, (SELECT MAX(s.BASIC_SALARY) FROM {P}PR_STAFF_DEFAULT_SALARY_M s WHERE s.STAFF_ID=c.STAFF_ID AND s.DATE_END IS NULL) + NVL((SELECT SUM(d.SALARY_ITEM_AMOUNT) FROM {P}PR_STAFF_DEFAULT_SALARY_D d WHERE d.STAFF_ID=c.STAFF_ID AND d.DATE_START=(SELECT MAX(s2.DATE_START) FROM {P}PR_STAFF_DEFAULT_SALARY_M s2 WHERE s2.STAFF_ID=c.STAFF_ID AND s2.DATE_END IS NULL)),0) TOT FROM {P}PS_STAFF_CONTRACT c JOIN {P}STAFF_MASTER m ON m.staff_id=c.STAFF_ID WHERE c.STATUS='A' AND c.CURRENT_CONTRACT='Y') x GROUP BY (CASE WHEN x.ORG IN ('001','002','003','004') THEN '0'||SUBSTR(x.ORG,3,1) ELSE SUBSTR(x.ORG,1,2) END), CASE WHEN x.NAT={SAUDI} THEN 'S' ELSE 'N' END ORDER BY 1,2
